 async function openNotification(item){
  const t=item.target,uuid=/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/i;
  if(!t||!uuid.test(t.reviewId)||typeof t.releaseId!=='string'||!Number.isFinite(Date.parse(t.releaseId))||t.at!==undefined&&(!Number.isFinite(t.at)||t.at<0||t.at>604800)||t.entryId&&!uuid.test(t.entryId)||t.threadId&&(!uuid.test(t.threadId)||!t.entryId))throw new Error('Invalid notification target.');
  const {review}=await api(`/api/replay/view/${t.reviewId}`);
  if(notificationViewer?.id===t.reviewId){if(t.releaseId!==review.releasedAt||notificationViewer.releasedAt!==review.releasedAt){throw new Error('This review has changed. Reopen it to see the latest feedback; the old timestamp was not opened.');}await notificationViewer.open(t);return;}
  if(dirty&&!confirm('Discard unsaved review edits to open this notification?'))throw new Error('Your draft was kept. The notification remains unread.');
  if(t.releaseId!==review.releasedAt)throw new Error('This notification refers to an earlier release. Open the latest breakdown from your reviews.');
  dirty=false;history.replaceState(null,'',review.permissions?.canEdit?`/replay?review=${t.reviewId}`:`/replay/view/${t.reviewId}`);
  if(review.permissions?.canEdit)await editor(t.reviewId);else await viewer(t.reviewId,false);
  await notificationViewer.open(t);
 }
